document.addEventListener('click',async e=>{const tab=e.target.closest('[data-view]');if(tab){view=tab.dataset.view;const u=new URL(location.href);u.searchParams.set('view',view);history.replaceState(null,'',u);try{await render();}catch(e){error(e);}return;}const b=e.target.closest('[data-action]');if(!b)return;try{await busy(b,()=>act(b));}catch(e){error(e,$('#ac-dialog').open);}});
